// Interactive workflow proposal. Claude Code sessions are simulated, never executed.
const WM=WorkflowModel, CHANGE_DIR='.uspec/changes/refund-window/';
const FLOW_STEPS=['Describe','Change plan','Triage & write','Split plans','Implementation plans','Implement','Complete'];
const ROLE_NAMES={scope:'Process change.md',triage:'Triage documents',writer:'Write specifications',split:'Split plans',plans:'Make implementation plans',implement:'Implement plans'};
const REPORT_FILES={scope:'change-plan.md',triage:'triage.md',plans:'plans/',split:'plan-split.md',writer:'updated specifications'};
const initialFiles=[
 {path:'docs/product/support/refunds/rules.md',decision:'rewrite',change:'Extend refund eligibility from 14 to 30 days.',reason:'Source of the refund-window business rule.',comment:''},
 {path:'docs/system/services/payments/api.md',decision:'rewrite',change:'Align the API eligibility contract and boundary errors.',reason:'The payment contract exposes the refund deadline.',comment:''},
 {path:'docs/system/services/payments/logic.md',decision:'rewrite',change:'Update the eligibility rule and examples for day 30 and day 31.',reason:'Service behavior must match the new policy.',comment:''},
 {path:'docs/experience/ops-console/refunds/states.md',decision:'rewrite',change:'Update eligibility messaging and disabled states.',reason:'Operators need the revised refund deadline.',comment:''},
 {path:'docs/system/services/payments/storage.md',decision:'no-change',change:'Keep the current schema.',reason:'Delivery timestamps and refund records already support this rule.',comment:''}
];
function freshFlow(){return {step:0,phase:'triage',brief:sessionStorage.getItem('uspec-draft')||changeText,reports:{},sessions:[],approved:{},busy:null,done:false};}
let flow;try{flow=JSON.parse(sessionStorage.getItem('uspec-workflow-v6'))||freshFlow();flow.busy=null;for(const s of flow.sessions)if(s.state==='running')s.state='paused';}catch{flow=freshFlow();}
let currentFlowView='state',selectedSession=null,flowTimer=null,lastFlowDocument=null,currentPlanPath=null;
let planTimers=[],executionEpoch=0;
const flowPane=document.createElement('section');flowPane.id='workflow';$('state-frame').before(flowPane);
const terminalPane=document.createElement('section');terminalPane.id='agent-terminal';terminalPane.hidden=true;$('editor').after(terminalPane);
const terminalTab=document.createElement('button');terminalTab.id='agent-terminal-tab';terminalTab.hidden=true;document.querySelector('.tabs .spacer').before(terminalTab);
document.querySelector('.bottom-panel').hidden=true; // Session inventory belongs only to the state view.
const persistFlow=()=>sessionStorage.setItem('uspec-workflow-v6',JSON.stringify(flow));
function newSession(role){let s=flow.sessions.find(s=>s.role===role);if(s)return s;s={id:`cc-${role.startsWith('plan:')||role.startsWith('writer:')?role.split('/').pop().replace('.md',''):role}-${String(flow.sessions.length+1).padStart(2,'0')}`,role,label:ROLE_NAMES[role],state:'ready',revision:0,log:[],artifact:REPORT_FILES[role]||'implementation results'};flow.sessions.push(s);return s;}
function reportFor(kind){return flow.reports[kind]?WM.parse(flow.reports[kind],kind):null;}
function setReport(kind,r){flow.reports[kind]=WM.encode(r);persistFlow();}
function makeReport(kind){let files;if(kind==='scope')files=structuredClone(initialFiles);else if(kind==='triage')files=structuredClone((flow.approved.scope||reportFor('scope')).files);else if(kind==='writer')files=structuredClone((flow.approved.triage||reportFor('triage')).files);else if(kind==='plans')files=structuredClone((flow.approved.split||reportFor('split')).files);else {files=[{path:CHANGE_DIR+'plans/cli.md',decision:'implement',change:'Update CLI refund eligibility and boundary checks.',reason:'Command-line behavior and tests.',comment:'',nodes:['cli'],after:[]},{path:CHANGE_DIR+'plans/vscode.md',decision:'implement',change:'Update the VS Code refund controls and eligibility messages.',reason:'Editor behavior and UI tests.',comment:'',nodes:['vscode'],after:[CHANGE_DIR+'plans/cli.md']}];const selected=WM.selected(flow.approved.writer||reportFor('writer'));for(const plan of files){const related=selected.filter(f=>plan.path.endsWith('cli.md')?!f.path.includes('experience/'):f.path.includes('experience/'));plan.decision=related.length?'implement':'skip';plan.comment=related.filter(f=>f.comment).map(f=>f.path+': '+f.comment).join('\n');}const included=new Set(files.filter(f=>f.decision==='implement').map(f=>f.path));for(const plan of files)plan.after=plan.after.filter(p=>included.has(p));}
return {kind,title:kind==='scope'?'Refund window — change plan':kind==='triage'?'Refund window — impact decisions':kind==='writer'?'Refund window — specification updates':kind==='split'?'Refund window — plan split':'Refund window — plans',summary:'Extend the refund window from 14 to 30 days after delivery. Keep payout methods and approval roles unchanged.',files};}
function ensurePreview(n){for(const [kind,limit] of [['scope',1],['triage',2],['writer',3],['split',4]])if(n>=limit&&!flow.reports[kind]){setReport(kind,makeReport(kind));if(kind==='writer'){writerGroups().forEach(g=>{const s=writerSession(g);s.state='review';s.written=true;s.revision=1;s.log.push('Updated '+g.files.map(f=>f.path).join(', ')+'.');});}else{const s=newSession(kind);s.state='review';s.revision=1;s.log.push(`Wrote ${REPORT_FILES[kind]}.`);}}if(n>=4){if(!reportFor('plans'))preparePlanGeneration();if(n>=5)reportFor('plans').files.forEach(f=>{const s=planSession(f);s.generated=true;s.revision=Math.max(1,s.revision);s.state=n===6?'complete':'review';s.phase=n===6?'implementation':'generation';});}flow.step=n;flow.phase=n>=3?'written':'triage';flow.done=n===6;persistFlow();}
function hideFlow(){flowPane.hidden=true;terminalPane.hidden=true;terminalTab.classList.remove('active');}
const priorEditor=showEditor;showEditor=function(...args){currentPlanPath=null;hideFlow();currentFlowView='document';priorEditor(...args);lastFlowDocument={args,actions:$('editor-actions').innerHTML,editable:$('editor-text').contentEditable};};
const priorInspectNode=inspectNode;inspectNode=function(...args){hideFlow();currentFlowView='node';priorInspectNode(...args);};
const priorInspectType=inspectType;inspectType=function(...args){hideFlow();currentFlowView='node';priorInspectType(...args);};
openState=function(){currentFlowView='state';$('state-frame').hidden=true;$('editor').hidden=true;$('node-overview').hidden=true;terminalPane.hidden=true;flowPane.hidden=false;terminalTab.classList.remove('active');$('state-tab').classList.add('active');$('file-tab').classList.remove('active');$('node-tab').classList.remove('active');$('breadcrumbs').textContent='Changes › refund-window › Workflow';renderFlow();};
function flowButton(action,label,cls='secondary',extra=''){return `<button class="flow-button ${cls}" data-flow="${action}" ${extra}>${label}</button>`;}
function activeKind(){return flow.step===1?'scope':flow.step===2?(flow.phase!=='triage'?'writer':'triage'):flow.step===3?'split':flow.step===4?'plans':'implement';}
function artifactCard(kind){const s=newSession(kind);return `<div class="compact-artifact"><button data-flow="artifact" data-kind="${kind}">▤ ${REPORT_FILES[kind]} ↗</button>${agentControl(s)}</div>`;}
function fileTable(kind,editable){const r=reportFor(kind);if(!r)return '';const counts=WM.selected(r).length;return `<div class="review-list-heading"><h3>${kind==='plans'?'Plans':'Files'} <span>${counts}</span></h3><span>${counts} ${kind==='plans'?'to implement':'to rewrite'}</span></div><div class="review-files">${r.files.map((f,i)=>f.decision==='no-change'?'':`<article class="review-file"><div class="review-file-top"><button class="review-file-link" data-flow="file" data-kind="${kind}" data-index="${i}"><span>▤</span><span><strong>${escape(f.path.split('/').pop())}</strong><small>${escape(f.path.split('/').slice(0,-1).join('/'))}</small></span></button>${editable?`<select aria-label="Decision for ${escape(f.path)}" data-decision="${i}" data-kind="${kind}" ${flow.busy?'disabled':''}>${(kind==='plans'?[['implement','Implement'],['skip','Skip']]:[['rewrite','Rewrite'],['no-change','No change']]).map(([v,l])=>`<option value="${v}" ${f.decision===v?'selected':''}>${l}</option>`).join('')}</select>`:`<span class="decision-badge ${f.decision}">${kind==='writer'&&f.decision==='rewrite'?'Updated':f.decision==='no-change'?'No change':f.decision==='skip'?'Skip':f.decision==='implement'?'Implement':'Rewrite'}</span>`}</div>${f.after?.length?`<div class="depends-on">After: ${f.after.map(p=>escape(p.split('/').pop())).join(', ')}</div>`:''}${editable?`<details class="file-comment" ${f.comment?'open':''}><summary>${f.comment?'Comment added':'＋ Comment'}</summary><textarea aria-label="Comment for ${escape(f.path)}" data-comment="${i}" data-kind="${kind}" ${flow.busy?'disabled':''} placeholder="Constraints, corrections, or guidance for this file…">${escape(f.comment||'')}</textarea></details>`:f.comment?`<p class="saved-comment">Your comment: ${escape(f.comment)}</p>`:''}</article>`).join('')}</div>`;}
function agentControl(s){const labels={ready:'Ready',running:'Running',queued:'Queued',review:'Review',complete:'Done',paused:'Paused'};return `<span class="inline-agent"><span class="agent-state ${s.state}"><i></i>${s.phase==='generation'?(s.state==='running'?'Generating':s.generated?'Ready for review':labels[s.state]||'Ready'):labels[s.state]||'Ready'}</span>${flowButton('terminal','Open agent window','text',`data-session="${s.id}"`)}</span>`;}
function planSession(f){const role='plan:'+f.path;let s=flow.sessions.find(x=>x.role===role);if(!s){s=newSession(role);s.label=f.path.replace(CHANGE_DIR,'');s.artifact=s.label;s.state='ready';s.phase='generation';s.generated=false;s.revision=0;s.log=[];}return s;}
function preparePlanGeneration(){setReport('plans',makeReport('plans'));for(const f of reportFor('plans').files){const s=planSession(f);s.generated=false;s.state='ready';s.phase='generation';}persistFlow();}
function generationReady(){const r=reportFor('plans');return !!r&&WM.selected(r).every(f=>{const s=planSession(f);return s.generated&&!['running','queued'].includes(s.state);});}
function generatePlan(index){const f=reportFor('plans').files[index],s=planSession(f);if(s.state==='running'||f.decision==='skip')return;s.state='running';s.phase='generation';s.generated=false;s.log.push(`$ claude${s.revision?' --resume '+s.id:''}`,`Generate only ${f.path}.`,`Scope: ${(f.nodes||[]).join(', ')}.`,f.comment?'Guidance: '+f.comment:'Reading the approved split and specifications.');const epoch=executionEpoch;refreshExecution();planTimers.push(setTimeout(()=>{if(epoch!==executionEpoch)return;s.generated=true;s.state='review';s.revision++;s.log.push(`Wrote ${f.path} (revision ${s.revision}).`,'Ready for review.');refreshExecution();},5000+index*2000));}
function generatePendingPlans(){reportFor('plans').files.forEach((f,i)=>{if(f.decision==='implement'&&!planSession(f).generated)generatePlan(i);});}
function planRows(){const r=reportFor('plans');if(!r)return '';return `<div class="plan-list">${r.files.map((f,i)=>{const s=planSession(f),running=['running','queued'].includes(s.state);return `<article class="plan-row ${f.decision==='skip'?'is-skipped':''}"><div class="plan-title"><button class="plan-name" data-flow="file" data-kind="plans" data-index="${i}" ${s.generated?'':'disabled'}>▤ ${escape(f.path.replace(CHANGE_DIR,''))}${s.generated?' ↗':''}</button><span class="plan-node">${escape((f.nodes||[]).join(', '))}</span>${agentControl(s)}</div><div class="plan-controls"><span class="plan-dependency">${f.after?.length?'Implement after '+f.after.map(p=>escape(p.split('/').pop())).join(', '):''}</span>${flow.step===4?`<details class="file-comment" ${f.comment?'open':''}><summary>${f.comment?'Comment':'＋ Comment'}</summary><textarea aria-label="Comment for ${escape(f.path)}" data-comment="${i}" data-kind="plans" placeholder="Optional guidance…" ${running?'disabled':''}>${escape(f.comment||'')}</textarea></details>`:''}<div class="spacer"></div>${flow.step===4?`<select aria-label="Decision for ${escape(f.path)}" data-decision="${i}" data-kind="plans" ${running?'disabled':''}><option value="implement" ${f.decision==='implement'?'selected':''}>Implement</option><option value="skip" ${f.decision==='skip'?'selected':''}>Skip</option></select>${f.decision==='implement'?flowButton('generate-plan',running?'Generating…':s.generated?'Regenerate plan':'Generate plan','secondary',`data-index="${i}" ${running?'disabled':''}`):''}`:f.decision==='skip'?'<span class="muted">Skipped</span>':flowButton('run-plan',s.state==='complete'?'Run again':'Run plan','secondary',`data-index="${i}" ${running?'disabled':''}`)}</div></article>`;}).join('')}</div>`;}
function refreshExecution(){persistFlow();renderFlow();if(currentFlowView==='terminal')renderTerminal();else if(currentFlowView==='document'&&currentPlanPath){const f=reportFor('plans').files.find(f=>f.path===currentPlanPath);if(f)$('editor-actions').innerHTML=`<div class="artifact-editor-bar">${flowButton('state','Back to workflow')}${agentControl(planSession(f))}</div>`;}}
function startPlan(index){const r=reportFor('plans'),f=r.files[index],s=planSession(f);if(f.decision!=='implement'||s.state==='running')return;const dependencies=(f.after||[]).map(p=>r.files.find(x=>x.path===p));if(dependencies.some(d=>!d||planSession(d).state!=='complete')){s.state='queued';refreshExecution();return;}s.state='running';s.phase='implementation';s.log.push(`$ claude --resume ${s.id}`,'Implementing '+f.path,'Applying approved plan and verification.');const epoch=executionEpoch;refreshExecution();planTimers.push(setTimeout(()=>{if(epoch!==executionEpoch)return;s.state='complete';s.log.push('Implementation and checks complete (simulation).');const current=reportFor('plans');current.files.forEach((p,i)=>{if(planSession(p).state==='queued')startPlan(i);});if(WM.selected(current).every(p=>planSession(p).state==='complete')){flow.step=6;flow.done=true;}refreshExecution();},6500));}
function startImplementation(){if(!generationReady())throw Error('Generate and review each selected plan first.');const r=reportFor('plans');WM.validatePlans(r);flow.approved.plans=structuredClone(r);flow.step=5;flow.done=false;r.files.forEach(f=>{if(f.decision==='implement')planSession(f).state='queued';});if(!WM.selected(r).length){flow.step=6;flow.done=true;}else r.files.forEach((f,i)=>{if(f.decision==='implement')startPlan(i);});refreshExecution();}
function stopPlanTimers(){executionEpoch++;planTimers.forEach(clearTimeout);planTimers=[];flow.sessions.forEach(s=>{if(['running','queued'].includes(s.state))s.state='paused';});}
function writerGroups(){const r=reportFor('writer');if(!r)return [];const groups=new Map();for(const f of WM.selected(r)){const node=f.path.replace(/^docs\//,'').split('/').slice(0,-1).join('/');if(!groups.has(node))groups.set(node,{node,files:[]});groups.get(node).files.push(f);}return [...groups.values()];}
function writerSession(g){const role='writer:'+g.node;let s=flow.sessions.find(s=>s.role===role);if(!s){s=newSession(role);s.label=g.node;s.artifact=g.node;s.phase='writing';s.written=false;s.state='ready';}return s;}
function writersReady(){return writerGroups().every(g=>writerSession(g).written);}
function runNodeWriter(node){const groups=writerGroups(),g=groups.find(g=>g.node===node);if(!g)return;const s=writerSession(g);if(s.state==='running')return;s.state='running';s.written=false;flow.phase='writing';s.log.push(`$ claude${s.revision?' --resume '+s.id:''}`,`Update only node ${g.node}.`,`Files: ${g.files.map(f=>f.path).join(', ')}`,g.files.filter(f=>f.comment).map(f=>f.path+': '+f.comment).join('\n')||'Using approved triage decisions.');const epoch=executionEpoch;refreshExecution();planTimers.push(setTimeout(()=>{if(epoch!==executionEpoch)return;s.written=true;s.state='review';s.revision++;s.log.push(...g.files.map(f=>'Updated '+f.path+'.'),'Ready for review.');if(writersReady())flow.phase='written';refreshExecution();},4500+groups.indexOf(g)*1500));}
function startNodeWriters(){setReport('writer',makeReport('writer'));flow.phase='writing';const groups=writerGroups();groups.forEach(g=>{writerSession(g).written=false;});if(!groups.length)flow.phase='written';groups.forEach(g=>runNodeWriter(g.node));refreshExecution();}
function inlineDiffs(){const groups=writerGroups();const samples={
'rules.md':['A refund can be requested up to 14 days after delivery.','A refund can be requested up to 30 days after delivery.'],
'api.md':['refundEligible: daysSinceDelivery <= 14','refundEligible: daysSinceDelivery <= 30'],
'logic.md':['Reject refunds requested more than 14 days after delivery.','Reject refunds requested more than 30 days after delivery.'],
'states.md':['Show “Refund window expired” after day 14.','Show “Refund window expired” after day 30.']};return `<div class="node-diff-groups">${groups.map(g=>{const s=writerSession(g);return `<section class="node-diff-group" aria-label="${escape(g.node)}"><header class="node-diff-heading"><span>◇</span><strong>${escape(g.node)}</strong><small>${g.files.length} ${g.files.length===1?'file':'files'}</small>${agentControl(s)}${s.state==='paused'?flowButton('resume-writer','Resume','secondary',`data-node="${escape(g.node)}"`):''}</header><div class="diff-list">${g.files.map(f=>{if(!s.written)return `<div class="pending-node-file">▤ ${escape(f.path.split('/').pop())}<span>${s.state==='running'?'Writing…':'Pending'}</span></div>`;const lines=samples[f.path.split('/').pop()]||['Previous specification',f.change];return `<details class="inline-diff" open><summary><span>${escape(f.path.split('/').pop())}</span><span class="diff-count"><b>+1</b> <i>−1</i></span></summary><div class="diff-hunk"><div class="diff-line removed"><span>1</span><span>−</span><code>${escape(lines[0])}</code></div><div class="diff-line added"><span>1</span><span>+</span><code>${escape(lines[1])}</code></div></div></details>`;}).join('')}</div></section>`;}).join('')||'<div class="empty-note">No files selected.</div>'}</div>`;}

function splitRows(){const r=reportFor('split');if(!r)return '';return `<div class="plan-list">${WM.selected(r).map(f=>`<div class="split-row"><strong>${escape(f.path.replace(CHANGE_DIR,''))}</strong><span>${escape((f.nodes||[]).join(', '))}</span><small>${f.after?.length?'After '+f.after.map(p=>escape(p.split('/').pop())).join(', '):''}</small></div>`).join('')}</div>`;}
function renderFlow(){const kind=activeKind(),busy=!!flow.busy||(flow.step===2&&flow.phase!=='triage'&&!writersReady()),disabled=busy?'disabled':'';let content='';if(flow.step===0){content=`<div class="input-row"><span>▤ change.md</span><div class="spacer"></div>${flowButton('brief','Open change.md')}${flowButton('process','Process change.md','primary')}</div>`;}else if(flow.step<3){content=flow.step===2&&flow.phase!=='triage'?`<div class="plans-heading"><h2>Updated files</h2></div>${inlineDiffs()}`:`${artifactCard(kind)}${fileTable(kind,flow.step===2)}`;content+=`<div class="flow-actions">${flowButton('back','Go back','secondary',disabled)}<div class="spacer"></div>${flowButton('approve',busy?'Working…':flow.step===2&&flow.phase==='triage'?'Approve & write':'Approve','primary',!reportFor(kind)?'disabled':disabled)}</div>`;}else if(flow.step===3){content=reportFor('split')?`${artifactCard('split')}${splitRows()}<div class="flow-actions">${flowButton('back','Go back')}<div class="spacer"></div>${flowButton('approve','Approve split','primary')}</div>`:`<div class="input-row"><span>Split plans</span><div class="spacer"></div>${flow.sessions.some(s=>s.role==='split')?agentControl(newSession('split')):''}${flowButton('split',busy?'Splitting…':'Split into plans','primary',disabled)}</div><div class="flow-actions">${flowButton('back','Go back','secondary',disabled)}</div>`;}else{content=`<div class="plans-heading"><h2>${flow.step===4?'Plans':flow.step===5?'Implementation':'Complete'}</h2></div>${planRows()}<div class="flow-actions">${flowButton('back','Go back','secondary',flow.sessions.some(s=>['running','queued'].includes(s.state))?'disabled':'')}<div class="spacer"></div>${flow.step===4?`${!generationReady()?flowButton('generate','Generate pending plans','secondary',reportFor('plans').files.some(f=>f.decision==='implement'&&!planSession(f).generated&&planSession(f).state!=='running')?'':'disabled'):''}${flowButton('approve','Approve & implement','primary',generationReady()?'':'disabled')}`:flow.step===6?flowButton('close',flow.done==='closed'?'Closed':'Close change','primary',flow.done==='closed'?'disabled':''):''}</div>`;}
const running=flow.sessions.filter(s=>s.state==='running').length;
flowPane.innerHTML=`<div class="flow-header"><h1>refund-window</h1><span class="flow-summary">${running?running+' agent'+(running>1?'s':'')+' running':flow.done==='closed'?'Closed':flow.step===6?'Complete':flow.step===0?'Draft':'Awaiting review'}</span></div><ol class="flow-stepper">${FLOW_STEPS.map((label,i)=>`<li class="${i===flow.step?'current':i<flow.step?'done':''}"><span>${i<flow.step?'✓':i+1}</span>${label}</li>`).join('')}</ol><div class="workflow-body">${flow.busy&&flow.step===2&&flow.busy!==kind?`<div class="working-inline"><span>${escape(ROLE_NAMES[flow.busy])}</span>${agentControl(newSession(flow.busy))}</div>`:''}${content}</div>`;
$('scenario').value=String(flow.step);$('status-text').textContent=`refund-window · ${running?running+' running':FLOW_STEPS[flow.step]} · Simulation`;renderWorkflowTree();persistFlow();}

function renderWorkflowTree(){$('change-tree').innerHTML=`<button data-flow="state">◉ ${FLOW_STEPS[flow.step]}${flow.sessions.some(s=>s.state==='running')?' · Running':''}</button><button data-flow="brief">▤ change.md</button>${Object.keys(flow.reports).filter(k=>!['plans','writer'].includes(k)).map(kind=>`<button data-flow="artifact" data-kind="${kind}">▤ ${REPORT_FILES[kind]}</button>`).join('')}${reportFor('plans')?reportFor('plans').files.map((f,i)=>`<button data-flow="file" data-kind="plans" data-index="${i}">▤ ${escape(f.path.split('/').pop())}${flow.sessions.find(s=>s.role==='plan:'+f.path)?.state==='running'?' · Running':''}</button>`).join(''):''}`;}
function runFlowAgent(role,complete){if(flow.busy)return;const s=newSession(role);flow.busy=role;s.state='running';s.log.push(`$ claude${s.revision?' --resume '+s.id:''}`,`[preview] ${ROLE_NAMES[role]}`,`Reading approved input and per-file comments…`);persistFlow();if(currentFlowView==='state')renderFlow();else if(currentFlowView==='terminal')renderTerminal();flowTimer=setTimeout(()=>{s.revision++;s.state=role==='implement'?'complete':'review';s.log.push(role==='writer'?'Updated specification files.':role==='implement'?'Sample implementation verified.':`Wrote ${CHANGE_DIR+s.artifact} (revision ${s.revision}).`,'Waiting for your review.');flow.busy=null;complete();flowPane.scrollTop=0;persistFlow();if(currentFlowView==='state')renderFlow();else if(currentFlowView==='terminal')renderTerminal();},1600);}
function approveFlow(){try{const kind=activeKind(),r=reportFor(kind);if(!r||flow.busy||(kind==='writer'&&!writersReady()))return;if(flow.step===4)WM.validatePlans(r);flow.approved[kind]=structuredClone(r);if(kind==='writer')writerGroups().forEach(g=>{writerSession(g).state='complete';});else if(kind!=='plans')newSession(kind).state='complete';if(flow.step===1){flow.step=2;flow.phase='triage';runFlowAgent('triage',()=>setReport('triage',makeReport('triage')));}else if(flow.step===2&&flow.phase==='triage')startNodeWriters();else if(flow.step===2){delete flow.reports.split;delete flow.reports.plans;flow.step=3;}else if(flow.step===3){WM.validatePlans(r);delete flow.reports.plans;preparePlanGeneration();flow.step=4;}else if(flow.step===4)startImplementation();persistFlow();renderFlow();}catch(e){toast(e.message);}}
function openFlowArtifact(kind){if(['plans','writer'].includes(kind))return;const text=flow.reports[kind];if(!text)return;showEditor(CHANGE_DIR+REPORT_FILES[kind],text);$('editor-text').contentEditable='true';$('editor-actions').innerHTML=`<div class="artifact-editor-bar">${flowButton('save-artifact','Save & return','primary',`data-kind="${kind}"`)}${flowButton('state','Back to workflow')}</div>`;}
function openBrief(){showEditor(CHANGE_DIR+'change.md',flow.brief);$('editor-text').contentEditable='true';$('editor-actions').innerHTML=`<div class="artifact-editor-bar">${flowButton('save-brief','Save & return','primary')}${flowButton('state','Back to workflow')}</div>`;}
function openTerminal(id){const s=flow.sessions.find(s=>s.id===id);if(!s)return;selectedSession=id;currentFlowView='terminal';flowPane.hidden=true;$('state-frame').hidden=true;$('editor').hidden=true;$('node-overview').hidden=true;terminalPane.hidden=false;document.querySelectorAll('.tabs button').forEach(b=>b.classList.remove('active'));terminalTab.hidden=false;terminalTab.classList.add('active');terminalTab.textContent='›_ Claude Code · '+s.label;terminalTab.onclick=()=>openTerminal(selectedSession);$('breadcrumbs').textContent=`Changes › refund-window › ${s.label} › ${s.id}`;renderTerminal();}
function renderTerminal(){const s=flow.sessions.find(s=>s.id===selectedSession);if(!s)return;terminalPane.innerHTML=`<div class="vscode-terminal-toolbar"><span>›_ ${escape(s.label)}</span><span class="terminal-native-state">${s.state==='running'?'● Running':s.state==='queued'?'◌ Queued':''}</span><div class="spacer"></div>${flowButton('state','Back to workflow','text')}</div><div class="native-terminal-screen" tabindex="0" aria-label="Terminal preview"><pre>ak@example_product % claude

${escape(s.log.join('\n\n'))}${s.state==='running'?'\n\n⠋ Working…':''}</pre><span class="terminal-cursor" aria-hidden="true">▋</span></div>`;}
function goBack(){if(flow.busy||flow.sessions.some(s=>['running','queued'].includes(s.state)))return;if(flow.step===2&&flow.phase!=='triage'){flow.phase='triage';delete flow.approved.writer;}else{flow.step=Math.max(0,flow.step-1);if(flow.step===2)flow.phase='written';}for(const k of Object.keys(flow.approved))delete flow.approved[k];persistFlow();openState();}
function reviewFile(kind,index){const f=reportFor(kind).files[index];if(kind==='plans'){if(!planSession(f).generated)return;showEditor(f.path,`# ${f.path.split('/').pop()}\n\n**Nodes:** ${(f.nodes||[]).join(', ')}\n\n**After:** ${(f.after||[]).map(p=>p.split('/').pop()).join(', ')||'None'}\n\n## Approach\n${f.change}\n\n## Review guidance\n${f.comment||'No additional comments.'}\n\n## Verification\nTest day 30 and day 31. Keep payout methods unchanged.`);currentPlanPath=f.path;$('editor-actions').innerHTML=`<div class="artifact-editor-bar">${flowButton('state','Back to workflow')}${agentControl(planSession(f))}</div>`;}else doc(f.path.replace(/^docs\//,''));}

document.addEventListener('click',e=>{const el=e.target.closest('[data-flow]');if(!el||el.disabled)return;const a=el.dataset.flow;try{if(a==='state')openState();else if(a==='brief')openBrief();else if(a==='save-brief'){flow.brief=$('editor-text').textContent;sessionStorage.setItem('uspec-draft',flow.brief);persistFlow();openState();}else if(a==='process'){flow.step=1;runFlowAgent('scope',()=>{setReport('scope',makeReport('scope'));flow.step=1;});}else if(a==='resume-writer')runNodeWriter(el.dataset.node);else if(a==='split')runFlowAgent('split',()=>setReport('split',makeReport('split')));else if(a==='generate')generatePendingPlans();else if(a==='generate-plan')generatePlan(Number(el.dataset.index));else if(a==='artifact')openFlowArtifact(el.dataset.kind);else if(a==='save-artifact'){const kind=el.dataset.kind;WM.parse($('editor-text').textContent,kind);flow.reports[kind]=$('editor-text').textContent;delete flow.approved[kind];persistFlow();openState();}else if(a==='approve')approveFlow();else if(a==='back')goBack();else if(a==='continue')openTerminal(newSession(el.dataset.kind||activeKind()).id);else if(a==='terminal')openTerminal(el.dataset.session);else if(a==='file')reviewFile(el.dataset.kind,Number(el.dataset.index));else if(a==='run-plan'){flow.step=5;flow.done=false;startPlan(Number(el.dataset.index));}else if(a==='implement')startImplementation();else if(a==='close'){flow.done='closed';persistFlow();renderFlow();}}catch(err){toast(err.message);}});
document.addEventListener('change',e=>{if(!e.target.matches('[data-decision]'))return;const kind=e.target.dataset.kind,r=reportFor(kind);r.files[Number(e.target.dataset.decision)].decision=e.target.value;setReport(kind,r);delete flow.approved[kind];renderFlow();});
document.addEventListener('input',e=>{if(!e.target.matches('[data-comment]'))return;const kind=e.target.dataset.kind,r=reportFor(kind);r.files[Number(e.target.dataset.comment)].comment=e.target.value;setReport(kind,r);});
$('scenario').innerHTML=FLOW_STEPS.map((s,i)=>`<option value="${i}">${i+1}. ${s}</option>`).join('');$('scenario').onchange=e=>{clearTimeout(flowTimer);stopPlanTimers();flow.busy=null;flow.sessions.forEach(s=>{if(s.state==='running')s.state='paused';});ensurePreview(Number(e.target.value));openState();};
$('reset').onclick=()=>{clearTimeout(flowTimer);stopPlanTimers();flow=freshFlow();persistFlow();openState();};
$('state-tab').onclick=$('show-state').onclick=openState;$('change-title').onclick=e=>{e.preventDefault();openState();};$('file-tab').onclick=()=>{if(!lastFlowDocument)return openBrief();hideFlow();currentFlowView='document';$('editor').hidden=false;$('state-frame').hidden=true;$('node-overview').hidden=true;$('file-tab').classList.add('active');$('state-tab').classList.remove('active');$('node-tab').classList.remove('active');};$('sidebar-run').onclick=()=>{openState();if(flow.step===0){flow.step=1;runFlowAgent('scope',()=>{setReport('scope',makeReport('scope'));flow.step=1;});}else toast('Review this step in the state view before continuing.');};
$('explorer-new').onclick=()=>{clearTimeout(flowTimer);stopPlanTimers();flow=freshFlow();persistFlow();openBrief();};
const previousAction=action;action=function(a,key){if(['openChangeMd','continue','showLog','runAgents'].includes(a)){if(a==='openChangeMd')openBrief();else if(a==='runAgents')$('sidebar-run').click();else openTerminal(newSession(activeKind()).id);}else previousAction(a,key);};
$('info').onclick=()=>modal('Review-driven workflow','<p>Review Markdown proposals, inspect specification diffs, split work into plan files, then generate each plan.</p><p>Agent controls and status appear beside each document or plan. Open agent window resumes its session in the editor.</p><p>This is a browser simulation. The terminal is a read-only visual preview. In the extension, Claude Code uses a native VS Code terminal with unmodified input.</p>');
openState();
